begin;
create table if not exists public.mme_time_clock_events(clock_event_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),event_type text not null check(event_type in('clock_in','clock_out','break_start','break_end')),occurred_at timestamptz not null,source text not null default 'web' check(source in('web','mobile','pos','manager')),note text,recorded_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_time_clock_employee_time_idx on public.mme_time_clock_events(employee_auth_user_id,occurred_at desc);
create table if not exists public.mme_time_entries(time_entry_id uuid primary key default gen_random_uuid(),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),work_date date not null,clock_in timestamptz not null,clock_out timestamptz,break_minutes integer not null default 0 check(break_minutes>=0),regular_minutes integer not null default 0 check(regular_minutes>=0),overtime_minutes integer not null default 0 check(overtime_minutes>=0),entry_status text not null default 'draft' check(entry_status in('draft','submitted','approved','rejected','locked')),manager_auth_user_id uuid,manager_note text,approved_at timestamptz,created_at timestamptz not null default now(),check(clock_out is null or clock_out>=clock_in),check(clock_out is not null or entry_status='draft'));
create index if not exists mme_time_entries_employee_date_idx on public.mme_time_entries(employee_auth_user_id,work_date desc);
create table if not exists public.mme_payroll_periods(payroll_period_id uuid primary key default gen_random_uuid(),period_name text not null,period_start date not null,period_end date not null,pay_date date not null,period_status text not null default 'draft' check(period_status in('draft','open','review','approved','processing','paid','closed','cancelled')),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),check(period_end>=period_start),check(pay_date>=period_start));
create table if not exists public.mme_payroll_runs(payroll_run_id uuid primary key default gen_random_uuid(),payroll_period_id uuid not null references public.mme_payroll_periods(payroll_period_id),run_number integer not null default 1 check(run_number>0),run_status text not null default 'draft' check(run_status in('draft','calculating','review','approved','exported','paid','voided')),currency_code char(3) not null default 'USD',gross_total numeric(16,2) not null default 0 check(gross_total>=0),deduction_total numeric(16,2) not null default 0 check(deduction_total>=0),net_total numeric(16,2) not null default 0 check(net_total>=0),created_by_auth_user_id uuid not null,approved_by_auth_user_id uuid,created_at timestamptz not null default now(),unique(payroll_period_id,run_number));
create table if not exists public.mme_payroll_line_items(payroll_line_item_id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.mme_payroll_runs(payroll_run_id),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),pay_code text not null,line_description text not null,quantity numeric(12,4) not null default 0,rate numeric(14,4) not null default 0,amount numeric(14,2) not null,earning_or_deduction text not null check(earning_or_deduction in('earning','deduction','employer_contribution','memo')),source_reference text,created_at timestamptz not null default now());
create table if not exists public.mme_payroll_approvals(payroll_approval_id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.mme_payroll_runs(payroll_run_id),approval_stage text not null,decision text not null check(decision in('approved','rejected')),decision_note text,actor_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_paystub_records(paystub_id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.mme_payroll_runs(payroll_run_id),employee_auth_user_id uuid not null references public.mme_employee_profiles(employee_auth_user_id),storage_bucket text not null default 'mme-payroll-private',storage_path text not null,sha256 char(64) not null,issued_at timestamptz,created_at timestamptz not null default now(),unique(payroll_run_id,employee_auth_user_id),check(sha256 ~ '^[a-f0-9]{64}$'));
create table if not exists public.mme_payroll_payment_batches(payment_batch_id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.mme_payroll_runs(payroll_run_id),payment_method text not null check(payment_method in('ach','check','manual')),provider_reference text,payment_status text not null default 'draft' check(payment_status in('draft','submitted','confirmed','failed','cancelled')),total_amount numeric(16,2) not null check(total_amount>=0),currency_code char(3) not null default 'USD',submitted_at timestamptz,confirmed_at timestamptz,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_positive_pay_exports(positive_pay_export_id uuid primary key default gen_random_uuid(),payroll_run_id uuid not null references public.mme_payroll_runs(payroll_run_id),bank_account_reference text not null,storage_bucket text not null default 'mme-payroll-private',storage_path text not null,sha256 char(64) not null,export_status text not null default 'prepared' check(export_status in('prepared','submitted','acknowledged','rejected')),created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),check(sha256 ~ '^[a-f0-9]{64}$'));
do $$declare t text;begin foreach t in array array['mme_time_clock_events','mme_time_entries','mme_payroll_periods','mme_payroll_runs','mme_payroll_line_items','mme_payroll_approvals','mme_paystub_records','mme_payroll_payment_batches','mme_positive_pay_exports'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end$$;
commit;